; phystest.s -- runs the physics alone on a fixed input script and keeps a
; snapshot of the bike state after the marked segments, for
; tests/test_physics.py. The script is physscript.inc, generated by the test:
; 5 bytes per segment (ticks, throttle, brake, lean, snapshot?), then 0.
; trick_tick runs after every tick: its state is compared at the end.

MUL_TABLES = $0800
MUL_ACC    = 1
.include "math.inc"
.include "physconst.inc"

.segment "ZEROPAGE"
snap_ptr: .res 2
scr_ptr: .res 2
left:   .res 1

.segment "CODE"
start:
        JSR     mul_init
        LDA     #48
        JSR     phys_reset
        JSR     trick_reset
        LDA     #<LAP_LEN               ; a looping track, or 0
        STA     lap_len
        LDA     #>LAP_LEN
        STA     lap_len+1
        LDA     #<snaps
        STA     snap_ptr
        LDA     #>snaps
        STA     snap_ptr+1
        LDA     #<script
        STA     scr_ptr
        LDA     #>script
        STA     scr_ptr+1
@seg:   LDY     #0
        LDA     (scr_ptr),Y
        BEQ     done
        STA     left
        INY
        LDA     (scr_ptr),Y
        STA     in_throttle
        INY
        LDA     (scr_ptr),Y
        STA     in_brake
        INY
        LDA     (scr_ptr),Y
        STA     in_lean
@tick:  JSR     phys_tick
        JSR     trick_tick              ; the points too (tools/tricks.py)
        DEC     left
        BNE     @tick
        LDY     #4
        LDA     (scr_ptr),Y
        BEQ     @next
        LDY     #STATE_LEN-1
@snap:  LDA     pt_xf,Y
        STA     (snap_ptr),Y
        DEY
        BPL     @snap
        CLC
        LDA     snap_ptr
        ADC     #STATE_LEN
        STA     snap_ptr
        BCC     @next
        INC     snap_ptr+1
@next:  CLC
        LDA     scr_ptr
        ADC     #5
        STA     scr_ptr
        BCC     @seg
        INC     scr_ptr+1
        BNE     @seg
done:   JMP     done

.include "physics.inc"
.include "tricks.inc"
.include "mul.asm"

STATE_LEN = laps + 1 - pt_xf

.segment "RODATA"
TRACK_LEN = 4096
.include "physscript.inc"
track_h: .incbin "track1.bin"

.segment "BSS"
snaps:  .res STATE_LEN * NSNAPS
